#!/bin/bash
set -e
python3 - <<'PY'
import pathlib,hashlib,base64,gzip
p=pathlib.Path('/tmp/ai-youth-4938bb96d4b896e2.b64')
assert not p.is_symlink()
encoded=p.read_text()+''
assert hashlib.sha256(encoded.encode()).hexdigest()=='4938bb96d4b896e2395d05b2571b1eb0c2dd6fd5644f5c0229bc9fb5daf81c8c', 'Upload checksum mismatch'
exec(compile(gzip.decompress(base64.b64decode(encoded)),'youth-deploy','exec'))
p.unlink()
PY
